namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Description { get; set; } = "";
    public List<string> Ingredients { get; set; } = new();
    public List<string> Steps { get; set; } = new();
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;
    private readonly Lock _lock = new();

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            // Breakfast
            new Recipe
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Description = "Fluffy buttermilk pancakes perfect for a lazy weekend morning.",
                Ingredients = new() { "1½ cups all-purpose flour", "3½ tsp baking powder", "1 tbsp sugar", "¼ tsp salt", "1¼ cups milk", "1 egg", "3 tbsp melted butter" },
                Steps = new() { "Mix flour, baking powder, sugar and salt.", "Make a well and pour in milk, egg and butter; mix until smooth.", "Heat a griddle over medium-high heat and pour batter.", "Cook until bubbles form, then flip and cook until golden." },
                AverageRating = 4.5, RatingCount = 12
            },
            new Recipe
            {
                Id = 2, Title = "Avocado Toast", Category = "Breakfast",
                Description = "Simple yet delicious avocado toast with a kick of chili flakes.",
                Ingredients = new() { "2 slices sourdough bread", "1 ripe avocado", "1 tbsp lemon juice", "Salt and pepper to taste", "Red chili flakes", "1 tbsp olive oil" },
                Steps = new() { "Toast the bread until golden and crispy.", "Mash the avocado with lemon juice, salt and pepper.", "Spread avocado mixture on toast.", "Drizzle with olive oil and sprinkle chili flakes." },
                AverageRating = 4.2, RatingCount = 8
            },
            new Recipe
            {
                Id = 3, Title = "Veggie Omelette", Category = "Breakfast",
                Description = "A hearty omelette packed with fresh vegetables and cheese.",
                Ingredients = new() { "3 eggs", "¼ cup diced bell peppers", "¼ cup diced onions", "¼ cup sliced mushrooms", "¼ cup shredded cheddar cheese", "Salt and pepper", "1 tbsp butter" },
                Steps = new() { "Beat eggs with salt and pepper.", "Melt butter in a non-stick pan over medium heat.", "Sauté vegetables until tender, then pour in eggs.", "Cook until set, add cheese, fold and serve." },
                AverageRating = 4.0, RatingCount = 6
            },

            // Lunch
            new Recipe
            {
                Id = 4, Title = "Caesar Salad", Category = "Lunch",
                Description = "Crisp romaine lettuce with creamy Caesar dressing and crunchy croutons.",
                Ingredients = new() { "1 head romaine lettuce", "½ cup Caesar dressing", "¼ cup grated Parmesan", "1 cup croutons", "2 grilled chicken breasts (optional)", "Black pepper" },
                Steps = new() { "Wash and chop the romaine lettuce.", "Toss with Caesar dressing.", "Top with croutons, Parmesan and sliced chicken.", "Season with black pepper and serve." },
                AverageRating = 4.3, RatingCount = 10
            },
            new Recipe
            {
                Id = 5, Title = "Grilled Chicken Wrap", Category = "Lunch",
                Description = "A satisfying wrap with grilled chicken, veggies and ranch dressing.",
                Ingredients = new() { "1 large flour tortilla", "1 grilled chicken breast, sliced", "½ cup shredded lettuce", "¼ cup diced tomatoes", "¼ cup shredded cheese", "2 tbsp ranch dressing" },
                Steps = new() { "Warm the tortilla in a dry skillet.", "Layer chicken, lettuce, tomatoes and cheese.", "Drizzle with ranch dressing.", "Roll up tightly and slice in half." },
                AverageRating = 4.1, RatingCount = 7
            },

            // Dinner
            new Recipe
            {
                Id = 6, Title = "Spaghetti Bolognese", Category = "Dinner",
                Description = "A rich and hearty Italian classic with slow-simmered meat sauce.",
                Ingredients = new() { "400g spaghetti", "500g ground beef", "1 onion, diced", "3 cloves garlic, minced", "400g crushed tomatoes", "2 tbsp tomato paste", "1 tsp dried oregano", "Salt and pepper", "Parmesan for serving" },
                Steps = new() { "Cook spaghetti according to package directions.", "Brown ground beef with onion and garlic.", "Add tomatoes, tomato paste, oregano, salt and pepper.", "Simmer for 20 minutes, then serve over spaghetti with Parmesan." },
                AverageRating = 4.7, RatingCount = 15
            },
            new Recipe
            {
                Id = 7, Title = "Chicken Stir-Fry", Category = "Dinner",
                Description = "Quick and colorful stir-fry with tender chicken and crisp vegetables.",
                Ingredients = new() { "2 chicken breasts, sliced", "1 bell pepper, sliced", "1 cup broccoli florets", "1 carrot, julienned", "3 tbsp soy sauce", "1 tbsp sesame oil", "1 tbsp cornstarch", "2 cloves garlic, minced", "Cooked rice for serving" },
                Steps = new() { "Mix soy sauce, sesame oil and cornstarch for the sauce.", "Stir-fry chicken in a hot wok until cooked through.", "Add vegetables and garlic, stir-fry 3-4 minutes.", "Pour in sauce, toss to coat and serve over rice." },
                AverageRating = 4.4, RatingCount = 9
            },
            new Recipe
            {
                Id = 8, Title = "Baked Salmon", Category = "Dinner",
                Description = "Perfectly baked salmon fillets with a lemon-herb butter glaze.",
                Ingredients = new() { "4 salmon fillets", "2 tbsp butter, melted", "2 tbsp lemon juice", "2 cloves garlic, minced", "1 tsp dried dill", "Salt and pepper", "Lemon slices for garnish" },
                Steps = new() { "Preheat oven to 200°C (400°F).", "Place salmon on a lined baking sheet.", "Mix butter, lemon juice, garlic and dill; brush over salmon.", "Bake 12-15 minutes until salmon flakes easily." },
                AverageRating = 4.6, RatingCount = 11
            },

            // Desserts
            new Recipe
            {
                Id = 9, Title = "Chocolate Brownies", Category = "Desserts",
                Description = "Fudgy, rich chocolate brownies that are impossibly easy to make.",
                Ingredients = new() { "½ cup butter", "1 cup sugar", "2 eggs", "⅓ cup cocoa powder", "½ cup all-purpose flour", "¼ tsp salt", "¼ tsp baking powder", "1 tsp vanilla extract" },
                Steps = new() { "Preheat oven to 175°C (350°F) and grease a baking pan.", "Melt butter, stir in sugar, eggs and vanilla.", "Mix in cocoa, flour, salt and baking powder.", "Spread in pan and bake 25-30 minutes." },
                AverageRating = 4.8, RatingCount = 20
            },
            new Recipe
            {
                Id = 10, Title = "Vanilla Panna Cotta", Category = "Desserts",
                Description = "Silky smooth Italian custard dessert with a vanilla bean flavor.",
                Ingredients = new() { "2 cups heavy cream", "¼ cup sugar", "1 tsp vanilla extract", "2¼ tsp gelatin powder", "3 tbsp cold water", "Fresh berries for serving" },
                Steps = new() { "Bloom gelatin in cold water for 5 minutes.", "Heat cream and sugar until just simmering.", "Remove from heat, stir in gelatin until dissolved, add vanilla.", "Pour into molds and refrigerate at least 4 hours." },
                AverageRating = 4.5, RatingCount = 8
            },

            // Snacks
            new Recipe
            {
                Id = 11, Title = "Guacamole & Chips", Category = "Snacks",
                Description = "Fresh and zesty guacamole with crispy tortilla chips.",
                Ingredients = new() { "3 ripe avocados", "1 lime, juiced", "½ cup diced onion", "¼ cup chopped cilantro", "1 diced jalapeño", "Salt to taste", "Tortilla chips" },
                Steps = new() { "Mash avocados in a bowl to desired consistency.", "Stir in lime juice, onion, cilantro, jalapeño and salt.", "Taste and adjust seasoning.", "Serve immediately with tortilla chips." },
                AverageRating = 4.6, RatingCount = 14
            },
            new Recipe
            {
                Id = 12, Title = "Caprese Skewers", Category = "Snacks",
                Description = "Bite-sized skewers with mozzarella, tomato and fresh basil.",
                Ingredients = new() { "1 pint cherry tomatoes", "8 oz fresh mozzarella balls", "Fresh basil leaves", "2 tbsp balsamic glaze", "1 tbsp olive oil", "Salt and pepper" },
                Steps = new() { "Thread a tomato, basil leaf and mozzarella ball onto each skewer.", "Arrange on a serving platter.", "Drizzle with olive oil and balsamic glaze.", "Season with salt and pepper." },
                AverageRating = 4.3, RatingCount = 6
            },
        };

        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public List<string> GetCategories() =>
        new() { "Breakfast", "Lunch", "Dinner", "Desserts", "Snacks" };

    public List<Recipe> GetRecipesByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes
                .Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase))
                .ToList();
        }
    }

    public Recipe? GetRecipe(int id)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r => r.Id == id);
        }
    }

    public Recipe AddRecipe(Recipe recipe)
    {
        lock (_lock)
        {
            recipe.Id = _nextId++;
            _recipes.Add(recipe);
            return recipe;
        }
    }

    public void AddRating(int recipeId, int stars)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is null || stars < 1 || stars > 5) return;

            var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
        }
    }
}

