                            <p class="card-text text-muted">@recipe.Description</p>
                        </div>
                        <div class="card-footer bg-transparent d-flex justify-content-between align-items-center">
                            <span class="text-warning">
                                @for (int i = 1; i <= 5; i++)
                                {
                                    @(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")
                                }
                            </span>
                            <small class="text-muted">@recipe.AverageRating.ToString("0.0") (@recipe.RatingCount ratings)</small>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

