@rendermode InteractiveServer
@inject RecipeService RecipeService

<div class="d-flex align-items-center gap-3">
    <span style="font-size: 1.5rem; cursor: pointer;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span @onclick="() => SubmitRating(star)" class="text-warning">@(star <= (int)Math.Round(currentAverage) ? "★" : "☆")</span>
        }
    </span>
    <span class="text-muted">@currentAverage.ToString("0.0") (@currentCount ratings)</span>
    @if (showThanks)
    {
        <span class="badge bg-success">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private double currentAverage;
    private int currentCount;
    private bool showThanks;
    private CancellationTokenSource? _cts;

    protected override void OnParametersSet()
    {
        currentAverage = AverageRating;
        currentCount = RatingCount;
    }

    private async Task SubmitRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);

        var updated = RecipeService.GetRecipe(RecipeId);
        if (updated is not null)
        {
            currentAverage = updated.AverageRating;
            currentCount = updated.RatingCount;
        }

        showThanks = true;
        StateHasChanged();

        _cts?.Cancel();
        _cts = new CancellationTokenSource();
        try
        {
            await Task.Delay(2000, _cts.Token);
            showThanks = false;
        }
        catch (TaskCanceledException) { }
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1 class="mb-4">Submit a Recipe</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Recipe submitted successfully!</h4>
        <p>Your recipe "<strong>@submittedRecipe!.Title</strong>" has been added.</p>
        <a href="recipe/@submittedRecipe.Id" class="btn btn-primary">View Recipe</a>
        <button class="btn btn-outline-secondary ms-2" @onclick="ResetForm">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger mb-3" />

        <div class="mb-3">
            <label for="title" class="form-label">Title</label>
            <InputText id="title" class="form-control" @bind-Value="model.Title" />
            <ValidationMessage For="() => model.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="model.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
            </InputSelect>
            <ValidationMessage For="() => model.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="description" class="form-label">Description</label>
            <InputTextArea id="description" class="form-control" rows="3" @bind-Value="model.Description" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="model.Ingredients" />
            <ValidationMessage For="() => model.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="model.Steps" />
            <ValidationMessage For="() => model.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private SubmitRecipeModel model = new();
    private bool submitted;
    private Recipe? submittedRecipe;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = model.Title,
            Category = model.Category,
            Description = model.Description ?? "",
            Ingredients = model.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = model.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        };

        submittedRecipe = RecipeService.AddRecipe(recipe);
        submitted = true;
    }

    private void ResetForm()
    {
        model = new();
        submitted = false;
        submittedRecipe = null;
    }
}

using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class SubmitRecipeModel
{
    [Required(ErrorMessage = "Title is required.")]
    public string Title { get; set; } = "";

    [Required(ErrorMessage = "Category is required.")]
    public string Category { get; set; } = "";

    public string? Description { get; set; }

    [Required(ErrorMessage = "At least one ingredient is required.")]
    public string Ingredients { get; set; } = "";

    [Required(ErrorMessage = "At least one step is required.")]
    public string Steps { get; set; } = "";
}

